  "Smart paste": { de: "Intelligent einfügen", fr: "Collage intelligent", es: "Pegado inteligente" },
  "Someone asked you to take a look.": { de: "Jemand hat dich gebeten, mal draufzuschauen.", fr: "Quelqu'un t'a demandé d'y jeter un œil.", es: "Alguien te pidió que le echaras un vistazo." },
  "Start a session with 'New worktree' to let agents work side by side without touching each other's files.": { de: "Starte eine Sitzung mit 'Neuer Worktree', damit Agents nebeneinander arbeiten, ohne die Dateien der anderen anzufassen.", fr: "Lance une session avec « Nouveau worktree » pour que les agents travaillent côte à côte sans toucher aux fichiers des autres.", es: "Inicia una sesión con «Nuevo worktree» para que los agentes trabajen en paralelo sin tocar los archivos de los demás." },
  "Start a track in Spotify, your browser or another player and you will see it here.": { de: "Starte einen Titel in Spotify, deinem Browser oder einem anderen Player, dann siehst du ihn hier.", fr: "Lance un morceau dans Spotify, ton navigateur ou un autre lecteur et tu le verras ici.", es: "Pon una canción en Spotify, tu navegador u otro reproductor y la verás aquí." },
  "Start GOWA automatically with Nook": { de: "GOWA automatisch mit Nook starten", fr: "Lancer GOWA automatiquement avec Nook", es: "Iniciar GOWA automáticamente con Nook" },
  "Status updates from your contacts don't notify you.": { de: "Statusupdates deiner Kontakte melden sich nicht.", fr: "Les mises à jour de statut de tes contacts ne te notifient pas.", es: "Las actualizaciones de estado de tus contactos no te avisan." },
  "Stop": { de: "Stoppen", fr: "Arrêter", es: "Detener" },
