  "Stored in your keychain": { de: "Im Schlüsselbund gespeichert", fr: "Enregistré dans ton trousseau", es: "Guardado en tu llavero" },
  "Stored in your keychain (paste again to replace)": { de: "Im Schlüsselbund gespeichert (erneut einfügen zum Ersetzen)", fr: "Enregistré dans ton trousseau (colle à nouveau pour remplacer)", es: "Guardado en tu llavero (vuelve a pegar para reemplazar)" },
  "Sure?": { de: "Sicher?", fr: "Sûr ?", es: "¿Seguro?" },
  "Switch Valorant on in Gamer Mode first": { de: "Schalte Valorant zuerst im Gamer Mode ein", fr: "Active d'abord Valorant dans le Gamer Mode", es: "Activa primero Valorant en Gamer Mode" },
  "Tab picks · 1–9 · Esc": { de: "Tab wählt · 1–9 · Esc", fr: "Tab choisit · 1–9 · Échap", es: "Tab elige · 1–9 · Esc" },
  "Take a screenshot now and let the brain read it": { de: "Jetzt einen Screenshot machen und vom Gehirn lesen lassen", fr: "Fais une capture d'écran maintenant et laisse le cerveau la lire", es: "Haz una captura ahora y deja que el cerebro la lea" },
  "Take over the gh sign-in": { de: "gh-Anmeldung übernehmen", fr: "Reprendre la connexion de gh", es: "Usar el inicio de sesión de gh" },
  "Terminals run on your computer, not on your phone.": { de: "Terminals laufen auf deinem Computer, nicht auf deinem Telefon.", fr: "Les terminaux tournent sur ton ordinateur, pas sur ton téléphone.", es: "Las terminales se ejecutan en tu ordenador, no en tu teléfono." },
  "Test": { de: "Testen", fr: "Tester", es: "Probar" },
