  "Use my GitHub CLI sign-in": { de: "Meine GitHub-CLI-Anmeldung nutzen", fr: "Utiliser ma connexion GitHub CLI", es: "Usar mi inicio de sesión de GitHub CLI" },
  "Used {n} times": { de: "{n}-mal genutzt", fr: "Utilisé {n} fois", es: "Usado {n} veces" },
  "User:password (optional)": { de: "Benutzer:Passwort (optional)", fr: "Utilisateur:mot de passe (facultatif)", es: "Usuario:contraseña (opcional)" },
  "Using GitLab on your own server? Fill in the address before you open the token page.": { de: "Nutzt du GitLab auf deinem eigenen Server? Gib die Adresse ein, bevor du die Token-Seite öffnest.", fr: "Tu utilises GitLab sur ton propre serveur ? Saisis l'adresse avant d'ouvrir la page des tokens.", es: "¿Usas GitLab en tu propio servidor? Escribe la dirección antes de abrir la página de tokens." },
