  "Waiting for Valorant": { de: "Wartet auf Valorant", fr: "En attente de Valorant", es: "Esperando a Valorant" },
  "Waiting for your review": { de: "Wartet auf dein Review", fr: "Attend ta review", es: "Esperando tu revisión" },
