  "Your latest merged pull requests.": { de: "Deine zuletzt gemergten Pull Requests.", fr: "Tes dernières pull requests mergées.", es: "Tus últimas pull requests fusionadas." },
  "Your own answer": { de: "Eigene Antwort", fr: "Ta propre réponse", es: "Tu propia respuesta" },
