  "{done} done · {failed} failed · {running} running": { de: "{done} fertig · {failed} fehlgeschlagen · {running} laufend", fr: "{done} terminées · {failed} échouées · {running} en cours", es: "{done} terminadas · {failed} fallidas · {running} en curso" },
  "{name} doesn't report costs.": { de: "{name} meldet keine Kosten.", fr: "{name} ne signale pas de coûts.", es: "{name} no informa costes." },
